<script>
import doctorsData from '../data/doctors.json'
import hospitalInfo from '../data/hospital-info.json'

export default {
  name: 'DoctorDetail',
  data: () => ({ doctor: null, doctors: doctorsData.doctors, info: hospitalInfo }),
  computed: {
    relatedDoctors() {
      if (!this.doctor) return []
      return this.doctors.filter((item) => item.id !== this.doctor.id && item.specialties.some((specialty) => this.doctor.specialties.includes(specialty))).slice(0, 3)
    },
    emergencyPhone() { return this.info.contact.phones.find((phone) => phone.type === 'emergency')?.number || this.info.contact.phones[0]?.number || '+234 703 344 9959' }
  },
  methods: {
    loadDoctor() { this.doctor = this.doctors.find((item) => item.id === Number(this.$route.params.id)) || null; if (!this.doctor) this.$router.replace('/doctors') },
    formatSpecialties(specialties) { return specialties.join(' & ') }
  },
  created() { this.loadDoctor() },
  watch: { '$route.params.id': 'loadDoctor' }
}
</script>

<template><div v-if="doctor" class="doctor-profile">
  <section class="profile-hero"><div class="site-container"><nav class="profile-breadcrumb" aria-label="Breadcrumb"><router-link to="/">Home</router-link><i class="bi bi-chevron-right"></i><router-link to="/doctors">Doctors</router-link><i class="bi bi-chevron-right"></i><span>{{ doctor.name }}</span></nav><div class="profile-hero__grid"><div><p class="profile-specialty">{{ formatSpecialties(doctor.specialties) }}</p><h1>{{ doctor.name }}</h1><p class="profile-role">{{ doctor.role }}</p><p class="profile-summary">{{ doctor.overview }}</p><router-link to="/book-appointment" class="button-primary">Book an appointment <i class="bi bi-arrow-right"></i></router-link></div><div class="profile-portrait"><img :src="doctor.image || 'https://placehold.co/720x840/e8f2f8/0b4f8a?text=BSH'" :alt="doctor.name"></div></div></div></section>
  <section class="section profile-content"><div class="site-container profile-layout"><main><article class="profile-about"><p class="eyebrow">About {{ doctor.name.split(' ').slice(-1)[0] }}</p><h2>Specialist care with a personal approach</h2><p>{{ doctor.overview }}</p><dl><div><dt>Division</dt><dd>{{ doctor.division }}</dd></div><div><dt>Specialties</dt><dd>{{ formatSpecialties(doctor.specialties) }}</dd></div></dl></article><div class="profile-cards"><article v-if="doctor.degrees?.length" class="profile-card"><span><i class="bi bi-mortarboard"></i></span><h2>Qualifications</h2><div v-for="degree in doctor.degrees" :key="degree.degree"><h3>{{ degree.degree }}</h3><p>{{ degree.school }}</p></div></article><article v-if="doctor.experiences?.length" class="profile-card"><span><i class="bi bi-briefcase"></i></span><h2>Areas of experience</h2><ul><li v-for="experience in doctor.experiences" :key="experience"><i class="bi bi-check-circle"></i>{{ experience }}</li></ul></article></div><section v-if="relatedDoctors.length" class="profile-related"><div class="section-heading"><p class="eyebrow">Our medical team</p><h2>Meet related specialists</h2></div><div><router-link v-for="item in relatedDoctors" :key="item.id" :to="{name:'DoctorDetail',params:{id:item.id}}" class="related-card"><img :src="item.image || 'https://placehold.co/160x160/e8f2f8/0b4f8a?text=BSH'" :alt="item.name"><span><small>{{ formatSpecialties(item.specialties) }}</small><strong>{{ item.name }}</strong><em>{{ item.role }}</em></span><i class="bi bi-arrow-up-right"></i></router-link></div></section></main><aside class="profile-aside"><section><i class="bi bi-calendar2-check"></i><h2>Book an appointment</h2><p>Request a consultation with {{ doctor.name }} and our team will get back to you.</p><router-link to="/book-appointment" class="button-primary">Request appointment</router-link><small><i class="bi bi-clock"></i> Response within 24 hours</small></section><section class="profile-contact"><h2>Need help?</h2><p>Speak with our patient care team to find the right next step.</p><a :href="`tel:${emergencyPhone.replace(/\s/g, '')}`"><i class="bi bi-telephone"></i>{{ emergencyPhone }}</a></section><section class="profile-emergency"><i class="bi bi-heart-pulse"></i><h2>Emergency care</h2><p>Our emergency department is open 24 hours, every day.</p><a :href="`tel:${emergencyPhone.replace(/\s/g, '')}`">Call emergency</a></section></aside></div></section>
</div></template>

